arguments.command:
python3 - <<'EOF'
import sqlite3,glob
for f in glob.glob('/app/.lemoncrow/workspace/*.sqlite'):
    try:
        c=sqlite3.connect('file:%s?mode=ro'%f,uri=True)
        t=[r[0] for r in c.execute("select name from sqlite_master where type='table'")]
        print(f,t)
    except Exception as e: print(f,e)
EOF
grep -c wal /logs/agent/lemoncrow-index.log; grep -i "main.db" /logs/agent/lemoncrow-index.log|head

